import { BACKEND_ATLAS } from '../../generated/backend-atlas.97a2dd66c443.mjs';
import { icon } from '../../core/icon.146a43f18e79.mjs';
import { t } from '../../core/i18n.966bca1c4f67.mjs';
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function buildCapabilitiesViewModel({query='',domain=null,method='all',language='en'}={}){const q=String(query).trim().toLowerCase();const entries=BACKEND_ATLAS.entries.filter(x=>(!domain||x.domain===domain)&&(method==='all'||x.method===method)&&(!q||`${x.method} ${x.path} ${x.domain} ${x.kind}`.toLowerCase().includes(q)));return Object.freeze({atlas:BACKEND_ATLAS,query,domain,method,language,entries:Object.freeze(entries)});}
export function renderCapabilitiesView(model=buildCapabilitiesViewModel()){const a=model.atlas;const language=model.language??'en';const read=a.entries.filter(x=>x.method==='GET').length;const write=a.total-read;return `<section class="capability-atlas"><header class="capability-atlas__hero"><div><p class="eyebrow">${esc(t('control.backendTruth',language))}</p><h1>${esc(t('control.capabilityAtlas',language))}</h1><p>${esc(t('control.atlasDescription',language))} <code>${esc(a.source)}</code></p></div><div class="atlas-receipt"><span>${esc(t('control.sourceReceipt',language))}</span><code>${esc(a.sourceSha256.slice(0,18))}…</code></div></header><div class="atlas-metrics"><span><strong>${a.total}</strong><small>${esc(t('control.routesPatterns',language))}</small></span><span><strong>${a.domains.length}</strong><small>${esc(t('control.backendDomains',language))}</small></span><span><strong>${read}</strong><small>${esc(t('control.readSurfaces',language))}</small></span><span><strong>${write}</strong><small>${esc(t('control.stateChanging',language))}</small></span></div><div class="atlas-layout"><aside class="atlas-domains"><header><strong>${esc(t('control.domains',language))}</strong><span>${a.domains.length}</span></header><label>${icon('search',{size:14})}<input type="search" data-atlas-search placeholder="${esc(t('control.filterRoutes',language))}" value="${esc(model.query)}"></label><div><button data-atlas-domain="" aria-pressed="${!model.domain}"><span>${esc(t('control.allDomains',language))}</span><strong>${a.total}</strong></button>${a.domains.map(d=>`<button data-atlas-domain="${esc(d.id)}" aria-pressed="${model.domain===d.id}"><span>${esc(d.id)}</span><strong>${d.count}</strong></button>`).join('')}</div></aside><main class="atlas-routes"><header><div><strong>${model.domain?esc(model.domain):esc(t('control.allBackendRoutes',language))}</strong><span>${model.entries.length} ${esc(t('control.visible',language))}</span></div><div class="segmented-control">${['all','GET','POST','PUT','DELETE'].map(m=>`<button data-atlas-method="${m}" aria-pressed="${model.method===m}">${m}</button>`).join('')}</div></header><div class="atlas-table"><div class="atlas-table__head"><span>${esc(t('control.method',language))}</span><span>${esc(t('control.route',language))}</span><span>${esc(t('control.domain',language))}</span><span>${esc(t('control.kind',language))}</span><span>${esc(t('control.source',language))}</span></div>${model.entries.map(e=>`<article><span class="method-badge" data-method="${esc(e.method)}">${esc(e.method)}</span><code>${esc(e.path)}</code><span>${esc(e.domain)}</span><span>${esc(e.kind)}</span><a href="../src/server/routes.mjs#L${e.line}" title="${esc(t('control.source',language))}">L${e.line}</a></article>`).join('')}</div></main></div></section>`}
